from pwn import process

def find_inputs():
    # Find x_28 and y_29 matching the conditions
    for x_28 in range(1, 100):  # Arbitrarily large range for x_28
        if (x_28 * (x_28 - 1)) & 1 == 0:
            for y_29 in range(10):  # y_29 must be less than 10
                yield x_28, y_29

def test_binary(x, y):
    # Test inputs on the binary
    p = process(['/home/ctfplayer/ctf_files/prophecy'])
    p.sendline(f"{x} {y}")  # Assuming binary expects inputs as space-separated
    output = p.recvall(timeout=2).decode(errors='ignore')
    p.close()
    return output

def main():
    for x, y in find_inputs():
        output = test_binary(x, y)
        if "flag{" in output:
            print(f"Found valid inputs: x_28={x}, y_29={y}")
            print(f"Output: {output}")
            break

if __name__ == "__main__":
    main()

