from pwn import *
import subprocess

def run_prophecy(x28, y29):
    try:
        proc = subprocess.run(["/home/ctfplayer/ctf_files/prophecy"], input=f"{x28}\n{y29}\n", text=True, capture_output=True, timeout=5)
        return proc.stdout, proc.stderr
    except subprocess.TimeoutExpired:
        return None, "Timeout Expired"

success_inputs = []

# Limiting x_28 to 1-5 and y_29 to 1-10 for initial testing
for x28 in range(1, 6):
    for y29 in range(1, 11):
        stdout, stderr = run_prophecy(x28, y29)

        if stdout and "flag" in stdout:  # Indicating potential advancement/flag behavior
            success_inputs.append((x28, y29, stdout))

with open("/home/ctfplayer/x28_y29_output.txt", "w") as result_file:
    for entry in success_inputs:
        result_file.write(f"x28: {entry[0]}, y29: {entry[1]}, Output: {entry[2]}\n")

print("Bruteforce Testing Complete.")

